import {api} from '../api.js';
import {clientAdminCorrectionApplies, renderClientAdminCorrection} from './client_admin_correction.js';
import {state, isGlobalAdmin, selectedTenant} from '../state.js';
import {$, $$, acronym, applyFieldErrors, badge, dateFmt, empty, esc, loading, modal, money, number, pageHead, pct, readonlyBanner, setActiveNav, statusTone, toast} from '../ui.js';

export async function renderClientPage(route, ctx, readOnlyOverride=false) {
  setActiveNav(route);
  const page=$('#page'); page.innerHTML=loading();
  if(!state.selectedTenantId){page.innerHTML=empty('Select a client','Choose a client from the top bar.');return;}
  try{
    if(clientAdminCorrectionApplies(route)){await renderClientAdminCorrection(route,page,ctx);return;}
    if(route==='home'||route==='client-360')return await home(page,ctx);
    if(route==='crm')return await crm(page,ctx,readOnlyOverride||isGlobalAdmin());
    if(route==='forecast')return await forecast(page,ctx,readOnlyOverride||isGlobalAdmin());
    if(route==='reports')return await reports(page,ctx);
    if(route==='piq')return await piq(page,ctx,readOnlyOverride||isGlobalAdmin());
    if(route==='solutions')return await solutions(page,ctx);
    if(route==='campaigns')return await campaigns(page,ctx,readOnlyOverride||isGlobalAdmin());
    if(route==='website')return await website(page,ctx);
    if(route==='organization')return await organization(page,ctx,readOnlyOverride||isGlobalAdmin());
    if(route==='training')return await training(page,ctx);
    return await home(page,ctx);
  }catch(error){page.innerHTML=empty('Unable to load this workspace',error.message);toast(error.message,'error');}
}

async function home(page,ctx){
  const data=await api(`/api/tenants/${state.selectedTenantId}/client360`);const t=data.tenant,m=data.metrics,f=data.financials;
  const global=isGlobalAdmin();
  page.innerHTML=`${pageHead(global?`${esc(t.name)} — Client 360`:`Welcome to ${esc(t.name)}`,global?'Commercial relationship, adoption, service health, and support evidence.':'Your company workspace for customers, sales, forecasting, marketing and growth.',global?`<button class="button secondary" id="return-portfolio">Return to Portfolio</button><button class="button" id="open-readonly-crm">View Client Operations — Read Only</button>`:'')}
  <section class="hero-card"><div><div class="eyebrow">${global?'AUTHORIZED CLIENT ADMINISTRATION':'CLIENT OPERATIONS'}</div><h2>${esc(t.name)}</h2><p>${esc(t.industry)} · ${esc(t.country)}</p></div><div class="hero-stat"><span>${global?'Client health':'Platform adoption'}</span><strong>${global?esc(t.health_status):pct(m.adoption_score)}</strong><small>${global?`Renewal risk: ${esc(t.renewal_risk)}`:`Training: ${pct(m.training_completion_pct)}`}</small></div></section>
  <div class="kpi-grid">${kpi(global?acronym('MRR'):'CRM accounts',global?money(f.mrr_cents):number(m.accounts),global?'Client contract schedule':'Active customer records')}${kpi(global?'Usage revenue':'Open opportunities',global?money(f.usage_revenue_cents):number(m.opportunities),global?'Current period':'Sales pipeline')}${kpi('Training',pct(m.training_completion_pct),'Assigned learning complete')}${kpi('Forecast accuracy',pct(m.forecast_accuracy_pct),'Current forecast performance')}</div>
  <div class="grid two"><section class="card"><h2>Quick actions</h2><div class="grid two">${global?`<button class="button secondary" data-route="pricing">Client Pricing</button><button class="button secondary" data-route="onboarding">Onboarding</button><button class="button secondary" data-route="crm">CRM — Read Only</button><button class="button secondary" data-route="organization">Sales Organization</button><button class="button secondary" data-route="reports">Management reports</button>`:`<button class="button" data-route="crm">Open CRM</button><button class="button secondary" data-route="forecast">Update forecast</button><button class="button secondary" data-route="solutions">Explore solutions</button><button class="button secondary" data-route="training">Training library</button>`}</div></section><section class="card"><h2>Active solutions</h2><div class="grid">${data.services.map(s=>`<div class="list-item"><span class="grow"><strong>${esc(s.catalog.name)}</strong><small class="muted">${esc(s.tenant_service.cadence)}</small></span>${badge(s.tenant_service.status,statusTone(s.tenant_service.status))}</div>`).join('')}</div></section></div>`;
  $('#return-portfolio')?.addEventListener('click',()=>ctx.navigate('portfolio'));
  $('#open-readonly-crm')?.addEventListener('click',async()=>{await api(`/api/tenants/${t.id}/support-access`,{method:'POST',body:{area:'CRM — Read Only',purpose:'Authorized support review'}});ctx.navigate('crm')});
  $$('[data-route]').forEach(btn=>btn.addEventListener('click',()=>ctx.navigate(btn.dataset.route)));
}

async function crm(page,ctx,readOnly){
  const [summary,accounts,leads,opportunities,activities,contacts]=await Promise.all([
    api(`/api/tenants/${state.selectedTenantId}/crm/summary`),api(`/api/tenants/${state.selectedTenantId}/accounts`),api(`/api/tenants/${state.selectedTenantId}/leads`),api(`/api/tenants/${state.selectedTenantId}/opportunities`),api(`/api/tenants/${state.selectedTenantId}/activities`),api(`/api/tenants/${state.selectedTenantId}/contacts`)
  ]);
  const tab=state.crmTab||'accounts';
  page.innerHTML=`${pageHead('CRM Workspace','Create and manage customer relationships from one accountable workspace.',readOnly?'':`<button class="button" id="crm-new">+ New</button>`)}${readOnly?readonlyBanner():''}
  <div class="kpi-grid">${kpi('Accounts',number(summary.accounts),'Customer relationships')}${kpi('Open opportunities',number(summary.opportunities),'Active pipeline')}${kpi('Leads',number(summary.leads),'New and qualified')}${kpi('Weighted pipeline',money(summary.weighted_pipeline_cents),'Probability-adjusted value')}</div>
  <div class="tabs" id="crm-tabs">${['accounts','leads','opportunities','contacts','activities'].map(x=>`<button class="tab ${tab===x?'active':''}" data-crm-tab="${x}">${title(x)}</button>`).join('')}</div><div id="crm-content" style="margin-top:14px">${crmTable(tab,{accounts:accounts.accounts,leads:leads.leads,opportunities:opportunities.opportunities,contacts:contacts.contacts,activities:activities.activities},readOnly)}</div>`;
  $$('[data-crm-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.crmTab=btn.dataset.crmTab;ctx.navigate('crm')}));
  $('#crm-new')?.addEventListener('click',()=>crmNewModal(tab,{accounts:accounts.accounts},ctx));
  $$('[data-account360]').forEach(btn=>btn.addEventListener('click',()=>account360Modal(btn.dataset.account360,readOnly,ctx)));
  $$('[data-convert-lead]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/leads/${btn.dataset.convertLead}/convert`,{method:'POST',body:{}});toast('Lead converted to account and opportunity');ctx.navigate('crm')}catch(e){toast(e.message,'error')}}));
  $$('[data-edit-opportunity]').forEach(btn=>btn.addEventListener('click',()=>editOpportunityModal(opportunities.opportunities.find(x=>x.id===btn.dataset.editOpportunity),ctx)));
}

function crmTable(tab,data,readOnly){
  if(tab==='accounts')return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Account</th><th>Owner</th><th>Team</th><th>Status</th><th>Prior value</th><th>Risk</th><th>Source</th><th></th></tr></thead><tbody>${data.accounts.map(a=>`<tr><td><strong>${esc(a.name)}</strong></td><td>${esc(a.owner_name)}</td><td>${esc(a.team_name)}</td><td>${badge(a.status,statusTone(a.status))}</td><td>${money(a.annual_value_cents)}</td><td>${badge(a.risk,statusTone(a.risk))}</td><td>${esc(a.source)}</td><td><button class="button secondary small" data-account360="${a.id}">Account 360</button></td></tr>`).join('')}</tbody></table></div></section>`;
  if(tab==='leads')return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Company</th><th>Contact</th><th>Email</th><th>Source</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${data.leads.map(l=>`<tr><td><strong>${esc(l.company_name||'—')}</strong></td><td>${esc(l.contact_name)}</td><td>${esc(l.email)}</td><td>${esc(l.source)}</td><td>${badge(l.status,statusTone(l.status))}</td><td>${dateFmt(l.created_at)}</td><td>${!readOnly&&l.status!=='Converted'?`<button class="button secondary small" data-convert-lead="${l.id}">Convert</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
  if(tab==='opportunities')return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Opportunity</th><th>Account</th><th>Stage</th><th>Value</th><th>Probability</th><th>Expected close</th><th>Source</th><th></th></tr></thead><tbody>${data.opportunities.map(o=>`<tr><td><strong>${esc(o.name)}</strong><div class="tiny muted">${esc(o.next_action||'')}</div></td><td>${esc(o.account_name||'')}</td><td>${badge(o.stage,statusTone(o.stage))}</td><td>${money(o.value_cents)}</td><td>${pct(o.probability_pct)}</td><td>${dateFmt(o.expected_close_date)}</td><td>${esc(o.source)}</td><td>${!readOnly?`<button class="button secondary small" data-edit-opportunity="${o.id}">Edit</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
  if(tab==='contacts')return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Contact</th><th>Account</th><th>Title</th><th>Email</th><th>Phone</th></tr></thead><tbody>${data.contacts.map(c=>`<tr><td><strong>${esc(`${c.first_name} ${c.last_name}`)}</strong></td><td>${esc(c.account_name)}</td><td>${esc(c.title)}</td><td>${esc(c.email)}</td><td>${esc(c.phone)}</td></tr>`).join('')}</tbody></table></div></section>`;
  return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Type</th><th>Subject</th><th>Details</th><th>Due</th><th>Created</th></tr></thead><tbody>${data.activities.map(a=>`<tr><td>${badge(a.activity_type,'gray')}</td><td><strong>${esc(a.subject)}</strong></td><td>${esc(a.body)}</td><td>${dateFmt(a.due_at)}</td><td>${dateFmt(a.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`;
}

function crmNewModal(defaultTab,data,ctx){
  const type=defaultTab==='activities'?'activity':defaultTab==='contacts'?'contact':defaultTab==='opportunities'?'opportunity':defaultTab==='leads'?'lead':'account';
  const tabs=['account','lead','contact','opportunity','activity'];
  let current=type;
  const render=(root)=>{
    $('.modal-body',root).innerHTML=`<div class="tabs" style="margin-bottom:18px">${tabs.map(x=>`<button class="tab ${x===current?'active':''}" data-new-type="${x}">${title(x)}</button>`).join('')}</div>${newForm(current,data.accounts)}`;
    $$('[data-new-type]',root).forEach(btn=>btn.addEventListener('click',()=>{
      current=btn.dataset.newType;
      render(root);
    }));
  };
  modal({
    title:'Create CRM record',
    body:'',
    wide:true,
    footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-crm-record">Save record</button>`,
    onOpen:(root,close)=>{
      render(root);
      $('#save-crm-record',root).addEventListener('click',async()=>{
        try{
          const form=$('#new-crm-form',root);
          if(!form.reportValidity())return;
          const fd=new FormData(form);
          const path=`/api/tenants/${state.selectedTenantId}/${current==='activity'?'activities':current+'s'}`;
          const body=Object.fromEntries(fd.entries());
          ['annual_value','value'].forEach(key=>{
            if(body[key]!==undefined){
              body[`${key}_cents`]=Math.round(Number(body[key])*100);
              delete body[key];
            }
          });
          if(body.probability_pct!==undefined)body.probability_pct=Number(body.probability_pct);
          await api(path,{method:'POST',body});
          toast(`${title(current)} created`);
          close();
          state.crmTab=current==='activity'?'activities':current+'s';
          ctx.navigate('crm');
        }catch(error){
          toast(error.message,'error');
        }
      });
    }
  });
}

function newForm(type,accounts){
  const accountOptions=[['','— Select account —'],...accounts.map(a=>[a.id,a.name])];
  if(type==='account')return `<form id="new-crm-form" class="form-grid">${field('Account name','name','text','',true)}${selectField('Status','status',[['Active','Active'],['Growing','Growing'],['At Risk','At Risk'],['Expected Termination','Expected Termination']])}${field('Prior annual value','annual_value','number',0)}${selectField('Source','source',[['Manual','Manual'],['Website','Website'],['Referral','Referral'],['ProspectIQ','ProspectIQ'],['Campaign','Campaign']])}${selectField('Risk','risk',[['Low','Low'],['Moderate','Moderate'],['High','High']])}<div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></form>`;
  if(type==='lead')return `<form id="new-crm-form" class="form-grid">${field('Company','company_name','text','',true)}${field('Contact name','contact_name','text','')}${field('Email','email','email','')}${field('Phone','phone','text','')}${selectField('Source','source',[['Manual','Manual'],['Website','Website'],['Referral','Referral'],['ProspectIQ','ProspectIQ']])}<div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></form>`;
  if(type==='contact')return `<form id="new-crm-form" class="form-grid">${selectField('Account','account_id',accountOptions)}${field('First name','first_name','text','',true)}${field('Last name','last_name','text','',true)}${field('Title','title','text','')}${field('Email','email','email','')}${field('Phone','phone','text','')}<div class="field"><label><input type="checkbox" name="primary_contact" value="true"> Primary contact</label></div></form>`;
  if(type==='opportunity')return `<form id="new-crm-form" class="form-grid">${field('Opportunity name','name','text','',true)}${selectField('Account','account_id',accountOptions)}${selectField('Stage','stage',[['Prospecting','Prospecting'],['Qualified','Qualified'],['Proposal','Proposal'],['Verbal Commitment','Verbal Commitment'],['Closed Won','Closed Won'],['Closed Lost','Closed Lost']])}${field('Value','value','number',0)}${field('Probability %','probability_pct','number',25)}${field('Expected close','expected_close_date','date','')}${selectField('Source','source',[['Manual','Manual'],['Website','Website'],['Referral','Referral'],['ProspectIQ','ProspectIQ'],['Campaign','Campaign']])}<div class="field full"><label>Next action</label><textarea name="next_action"></textarea></div></form>`;
  return `<form id="new-crm-form" class="form-grid">${selectField('Account','account_id',accountOptions)}${selectField('Activity type','activity_type',[['Call','Call'],['Email','Email'],['Meeting','Meeting'],['Task','Task'],['Note','Note']])}${field('Subject','subject','text','',true)}${field('Due date','due_at','datetime-local','')}<div class="field full"><label>Details</label><textarea name="body"></textarea></div></form>`;
}

async function account360Modal(accountId,readOnly,ctx){
  try{const data=await api(`/api/accounts/${accountId}/360`);modal({title:`${esc(data.account.name)} — Account 360`,body:`${readOnly?readonlyBanner():''}<div class="kpi-grid">${kpi('Annual value',money(data.account.annual_value_cents),'Client-reported prior value')}${kpi('Contacts',number(data.contacts.length),'Relationship contacts')}${kpi('Opportunities',number(data.opportunities.length),'Current and historical')}${kpi('Risk',data.account.risk,'Account health')}</div><div class="grid two"><section class="card flat"><h3>Contacts</h3>${data.contacts.map(c=>`<div class="list-item"><span class="grow"><strong>${esc(`${c.first_name} ${c.last_name}`)}</strong><small class="muted">${esc(c.title)} · ${esc(c.email)}</small></span></div>`).join('')||empty('No contacts','Add a contact from CRM.')}</section><section class="card flat"><h3>Recent activity</h3>${data.activities.slice(0,8).map(a=>`<div class="list-item"><span class="grow"><strong>${esc(a.subject)}</strong><small class="muted">${esc(a.activity_type)} · ${dateFmt(a.created_at)}</small></span></div>`).join('')||empty('No activity','Record the next customer interaction.')}</section></div><section class="card flat" style="margin-top:16px"><h3>Opportunities</h3>${data.opportunities.map(o=>`<div class="list-item"><span class="grow"><strong>${esc(o.name)}</strong><small class="muted">${esc(o.stage)} · ${pct(o.probability_pct)}</small></span><strong>${money(o.value_cents)}</strong></div>`).join('')||empty('No opportunities','Create an opportunity from CRM.')}</section>`,wide:true,footer:`<button class="button secondary" data-close-modal>Close</button>`});}catch(e){toast(e.message,'error')}
}
function editOpportunityModal(o,ctx){modal({title:`Edit ${esc(o.name)}`,body:`<form class="form-grid">${selectField('Stage','stage',[['Prospecting','Prospecting'],['Qualified','Qualified'],['Proposal','Proposal'],['Verbal Commitment','Verbal Commitment'],['Closed Won','Closed Won'],['Closed Lost','Closed Lost']],o.stage)}${field('Value','value','number',o.value_cents/100)}${field('Probability %','probability_pct','number',o.probability_pct)}${field('Expected close','expected_close_date','date',o.expected_close_date||'')}<div class="field full"><label>Next action</label><textarea name="next_action">${esc(o.next_action||'')}</textarea></div></form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-opportunity">Save</button>`,onOpen:(root,close)=>$('#save-opportunity',root).addEventListener('click',async()=>{try{await api(`/api/opportunities/${o.id}`,{method:'PATCH',body:{stage:$('[name=stage]',root).value,value_cents:Math.round(Number($('[name=value]',root).value)*100),probability_pct:Number($('[name=probability_pct]',root).value),expected_close_date:$('[name=expected_close_date]',root).value||null,next_action:$('[name=next_action]',root).value}});toast('Opportunity updated');close();ctx.navigate('crm')}catch(e){toast(e.message,'error')}})});}

async function forecast(page,ctx,readOnly){
  const data=await api(`/api/tenants/${state.selectedTenantId}/forecast`);
  if(!data.version){page.innerHTML=`${pageHead('Sales Forecasting','Create a fiscal-year forecast from client accounts.')}${readOnly?readonlyBanner():''}${empty('No forecast version','An authorized client leader can create the first forecast version.')}`;return;}
  const monthsByAccount={};data.months.forEach(m=>(monthsByAccount[m.account_id]??=[]).push(m));
  const totals=data.accounts.reduce((acc,a)=>{const rows=monthsByAccount[a.id]||[];acc.prior+=rows.reduce((s,m)=>s+m.prior_actual_cents,0);acc.forecast+=rows.reduce((s,m)=>s+m.forecast_cents,0);acc.actual+=rows.reduce((s,m)=>s+m.actual_cents,0);return acc},{prior:0,forecast:0,actual:0});
  page.innerHTML=`${pageHead('Sales Forecasting','Forecast the fiscal year by client and month using growth, flat performance, contraction, attrition, and actuals.')}${readOnly?readonlyBanner():''}
  <div class="kpi-grid">${kpi('Prior year',money(totals.prior),'Account-level actuals')}${kpi('Operating forecast',money(totals.forecast),data.version.name)}${kpi('Actual to date',money(totals.actual),'Entered or imported')}${kpi('Annual goal',money(data.version.annual_goal_cents),'Leadership target')}</div>
  <section class="table-card"><div class="table-toolbar"><h2>${esc(data.version.name)} · FY${data.version.fiscal_year}</h2><div class="grow"></div>${readOnly?'':`<button class="button secondary small" id="import-sales">Import sales data</button>`}</div><div class="table-wrap forecast-wrap"><table class="data-table forecast-table"><thead><tr><th class="sticky-col">Client account</th><th class="sticky-col-2">Status</th>${Array.from({length:12},(_,i)=>`<th>${new Date(2000,i,1).toLocaleString('en',{month:'short'})}</th>`).join('')}<th>Total</th></tr></thead><tbody>${data.accounts.map(a=>{const rows=(monthsByAccount[a.id]||[]).sort((x,y)=>x.month-y.month);return `<tr><td class="sticky-col"><strong>${esc(a.name)}</strong><div class="tiny muted">${esc(a.team_name)}</div></td><td class="sticky-col-2">${badge(a.status,statusTone(a.status))}</td>${rows.map(m=>`<td><input data-forecast-month="${m.id}" value="${(m.forecast_cents/100).toFixed(0)}" ${readOnly?'disabled':''} title="Prior: ${money(m.prior_actual_cents)} · Actual: ${money(m.actual_cents)}"></td>`).join('')}<td><strong>${money(rows.reduce((s,m)=>s+m.forecast_cents,0))}</strong></td></tr>`}).join('')}</tbody></table></div></section>`;
  $$('[data-forecast-month]').forEach(input=>input.addEventListener('change',async()=>{try{await api(`/api/forecast/months/${input.dataset.forecastMonth}`,{method:'PATCH',body:{forecast_cents:Math.round(Number(input.value)*100)}});toast('Forecast updated')}catch(e){toast(e.message,'error')}}));
  $('#import-sales')?.addEventListener('click',()=>salesImportModal(data,ctx));
}
function salesImportModal(data,ctx){modal({title:'Import prior-year or actual sales',body:`<p>Paste rows copied from Excel or Google Sheets. Format: <strong>Account | Month | Amount | Target</strong>.</p><div class="field"><label>Paste rows</label><textarea id="import-rows" style="min-height:220px" placeholder="Apex Distribution Center\t1\t12500\tprior_actual"></textarea></div><p class="tiny muted">Target may be prior_actual, forecast, or actual.</p>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="validate-import">Validate & import</button>`,onOpen:(root,close)=>$('#validate-import',root).addEventListener('click',async()=>{const rows=$('#import-rows',root).value.split(/\n/).filter(Boolean).map(line=>{const [account,month,amount,target='prior_actual']=line.split(/\t|,/);return {account:account?.trim(),month:Number(month),amount:Number(amount),target:target?.trim()}});try{const result=await api(`/api/tenants/${state.selectedTenantId}/sales-import`,{method:'POST',body:{version_id:data.version.id,rows}});toast(`Imported ${result.matched} rows${result.exceptions.length?`; ${result.exceptions.length} exceptions`:''}`);close();ctx.navigate('forecast')}catch(e){toast(e.message,'error')}})});}

async function reports(page){
  const data=await api(`/api/tenants/${state.selectedTenantId}/reports/ttm`);const s=data.summary||{};
  page.innerHTML=`${pageHead('Management Intelligence','Review performance from company totals to account-level evidence.')}
  <div class="kpi-grid">${kpi(acronym('TTM'),money(s.current_ttm_cents),'Current trailing 12 months')}${kpi('Prior TTM',money(s.prior_ttm_cents),'Comparison period')}${kpi('Forecast',money(s.forecast_cents),'Current active version')}${kpi('Accounts',number(s.account_count),'Included client accounts')}</div>
  <section class="table-card"><div class="table-toolbar"><h2>Trailing Twelve Months by account</h2><div class="grow"></div><button class="button secondary small" id="export-report">Export CSV</button></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Account</th><th>Team</th><th>Prior TTM</th><th>Current TTM</th><th>Change</th><th>Change %</th><th>Forecast</th></tr></thead><tbody>${data.accounts.map(a=>`<tr><td><strong>${esc(a.account_name)}</strong></td><td>${esc(a.team_name)}</td><td>${money(a.prior_ttm_cents)}</td><td>${money(a.current_ttm_cents)}</td><td class="${a.change_cents>=0?'positive':'negative'}">${money(a.change_cents)}</td><td class="${a.change_pct>=0?'positive':'negative'}">${pct(a.change_pct)}</td><td>${money(a.forecast_cents)}</td></tr>`).join('')}</tbody></table></div></section>`;
  $('#export-report').addEventListener('click',()=>downloadCsv('ttm-report.csv',['Account','Team','Prior TTM','Current TTM','Change','Change %','Forecast'],data.accounts.map(a=>[a.account_name,a.team_name,a.prior_ttm_cents/100,a.current_ttm_cents/100,a.change_cents/100,a.change_pct,a.forecast_cents/100])));
}

async function piq(page,ctx,readOnly){
  let data;try{data=await api(`/api/tenants/${state.selectedTenantId}/piq`)}catch(e){page.innerHTML=`${pageHead('ProspectIQ','Premium opportunity intelligence is available through the Solutions Center.')}${empty('ProspectIQ is not active','Explore the solution and submit a request from the Solutions Center.')}<div style="text-align:center"><button class="button" id="go-solutions">Open Solutions Center</button></div>`;$('#go-solutions').addEventListener('click',()=>ctx.navigate('solutions'));return;}
  page.innerHTML=`${pageHead('ProspectIQ','Discover, inspect, enhance, and move qualified opportunities into CRM.')}${readOnly?readonlyBanner():''}
  <div class="kpi-grid">${kpi('Priority opportunities',number(data.opportunities.length),'Scored and ranked')}${kpi('Enhanced',number(data.opportunities.filter(x=>x.enhanced).length),'Paid profile enhancements')}${kpi('Moved to CRM',number(data.opportunities.filter(x=>x.moved_to_crm).length),'Preserved source attribution')}${kpi('Payment mode',esc(data.payment_provider),'Configured payment provider')}</div>
  <section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Opportunity</th><th>Score</th><th>Signal</th><th>Evidence</th><th>Potential</th><th>Status</th><th></th></tr></thead><tbody>${data.opportunities.map(o=>`<tr><td><strong>${esc(o.company_name)}</strong></td><td><strong>${o.score}</strong></td><td>${esc(o.signal)}</td><td>${o.evidence_count}</td><td>${money(o.estimated_value_cents)}</td><td>${o.enhanced?badge('Enhanced','green'):badge('Profile available','purple')}</td><td>${readOnly?'':`<div style="display:flex;gap:6px">${!o.enhanced?`<button class="button small" data-enhance="${o.id}">Enhance · ${money(o.enhancement_price_cents||400)}</button>`:''}${!o.moved_to_crm?`<button class="button secondary small" data-move-crm="${o.id}">Move to CRM</button>`:badge('In CRM','green')}</div>`}</td></tr>`).join('')}</tbody></table></div></section>`;
  $$('[data-enhance]').forEach(btn=>btn.addEventListener('click',()=>enhanceModal(btn.dataset.enhance,ctx)));
  $$('[data-move-crm]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/piq/${btn.dataset.moveCrm}/move-to-crm`,{method:'POST',body:{}});toast('Opportunity moved to CRM');ctx.navigate('piq')}catch(e){toast(e.message,'error')}}));
}
function enhanceModal(id,ctx){modal({title:'Confirm paid profile enhancement',body:`<p>This enhancement is charged to the client’s configured payment method before the record is enhanced.</p><label class="list-item"><input type="checkbox" id="confirm-enhancement"><span>I authorize this per-record enhancement charge.</span></label>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="run-enhancement">Confirm & enhance</button>`,onOpen:(root,close)=>$('#run-enhancement',root).addEventListener('click',async()=>{if(!$('#confirm-enhancement',root).checked){toast('Confirmation is required','error');return}try{await api(`/api/piq/${id}/enhance`,{method:'POST',body:{payment_confirmation:true}});toast('Profile enhanced and transaction recorded');close();ctx.navigate('piq')}catch(e){toast(e.message,'error')}})});}

async function solutions(page,ctx){
  const data=await api(`/api/tenants/${state.selectedTenantId}/solutions`);const clientAdmin=state.user.tenant_role==='CLIENT_ADMIN';
  page.innerHTML=`${pageHead('Solutions Center','Use active capabilities and explore relevant additions for your company.')}
  <div class="solution-grid">${data.solutions.map(x=>`<section class="card solution-card"><div style="display:flex;justify-content:space-between;gap:12px"><div class="solution-icon">${solutionIcon(x.service.code)}</div>${badge(x.status,statusTone(x.status))}</div><h3>${esc(x.service.name)}</h3><p class="muted">${esc(x.service.description)}</p><div class="tiny"><strong>${x.service.cadence==='usage'?`${money(x.service.standard_price_cents)} per ${esc(x.service.unit)}`:`From ${money(x.service.standard_price_cents)} ${esc(x.service.cadence)}`}</strong></div><div class="solution-actions">${x.status==='Active'?`<button class="button" data-open-solution="${x.service.code}">Open solution</button>`:x.status==='Available'?`<button class="button secondary" data-explore-solution="${x.service.code}">Explore</button>${clientAdmin?`<button class="button" data-request-solution="${x.service.code}">Request This Solution</button>`:''}`:`<span class="muted">${esc(x.status)}</span>`}</div></section>`).join('')}</div>`;
  $$('[data-open-solution]').forEach(btn=>btn.addEventListener('click',()=>ctx.navigate(routeForService(btn.dataset.openSolution))));
  $$('[data-explore-solution]').forEach(btn=>btn.addEventListener('click',async()=>{await api(`/api/tenants/${state.selectedTenantId}/solution-interest`,{method:'POST',body:{service_code:btn.dataset.exploreSolution,event_type:'demo_view'}}).catch(()=>{});solutionDemo(data.solutions.find(x=>x.service.code===btn.dataset.exploreSolution),ctx)}));
  $$('[data-request-solution]').forEach(btn=>btn.addEventListener('click',()=>requestSolutionModal(data.solutions.find(x=>x.service.code===btn.dataset.requestSolution),ctx)));
}
function solutionDemo(item,ctx){
  const isPiq=item.service.code==='piq_access';
  const steps=isPiq?['Discover','Resolve entity','Assemble evidence','Score & prioritize','Review before spending','Confirm enhancement charge','Enrich profile','Move to CRM','Measure outcome']:['Plan the work','Edit every word','Approve explicitly','Schedule or deliver','Measure outcomes'];
  modal({title:`${esc(item.service.name)} — solution review`,body:`<section class="hero-card" style="padding:24px"><div><div class="eyebrow">SOLUTION OVERVIEW</div><h2 style="font-size:2.2rem">${esc(item.service.name)}</h2><p>${esc(item.service.description)}</p></div></section><div class="grid three">${steps.map((s,i)=>`<div class="card flat"><span class="step-number">${i+1}</span><strong>${esc(s)}</strong></div>`).join('')}</div><div class="section-block"><strong>Pricing shown for this client</strong><p>${item.service.cadence==='usage'?`${money(item.service.standard_price_cents)} per ${esc(item.service.unit)}`:`${money(item.service.standard_price_cents)} ${esc(item.service.cadence)}`}</p></div>`,wide:true,footer:`<button class="button secondary" data-close-modal>Close</button>${state.user.tenant_role==='CLIENT_ADMIN'?`<button class="button" id="demo-request">Request This Solution</button>`:''}`,onOpen:(root,close)=>$('#demo-request',root)?.addEventListener('click',()=>{close();requestSolutionModal(item,ctx)})});
}
function requestSolutionModal(item,ctx){modal({title:`Request ${esc(item.service.name)}`,body:`<p>Tell RMR what you would like to accomplish. No charge occurs until an approved service is activated.</p><form class="form-grid"><div class="field full"><label>What would you like help accomplishing?</label><textarea name="note"></textarea></div>${selectField('Preferred contact method','preferred_contact_method',[['Email','Email'],['Phone','Phone'],['Video meeting','Video meeting']])}${field('Best time to contact you','best_time','text','')}</form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="submit-solution-request">Submit request</button>`,onOpen:(root,close)=>$('#submit-solution-request',root).addEventListener('click',async()=>{try{await api(`/api/tenants/${state.selectedTenantId}/solution-requests`,{method:'POST',body:{service_code:item.service.code,note:$('[name=note]',root).value,preferred_contact_method:$('[name=preferred_contact_method]',root).value,best_time:$('[name=best_time]',root).value}});toast('Request submitted');close();ctx.navigate('solutions')}catch(e){toast(e.message,'error')}})});}

async function campaigns(page,ctx,readOnly){
  const data=await api(`/api/tenants/${state.selectedTenantId}/campaigns`);
  page.innerHTML=`${pageHead('Campaigns & Content','Plan, edit, approve, schedule, and measure customer-facing content.',readOnly?'':`<button class="button" id="new-campaign">+ New campaign</button>`)}${readOnly?readonlyBanner():''}
  <div class="grid three">${data.campaigns.map(c=>`<section class="card"><div style="display:flex;justify-content:space-between"><span class="badge gray">${esc(c.channel)}</span>${badge(c.status,statusTone(c.status))}</div><h3>${esc(c.title)}</h3><p class="muted">${esc(c.content)}</p><div class="tiny muted">${c.scheduled_at?`Scheduled ${dateFmt(c.scheduled_at)}`:'Not scheduled'}</div>${!readOnly?`<button class="button secondary small" data-edit-campaign="${c.id}" style="margin-top:14px">Edit</button>`:''}</section>`).join('')}</div>`;
  $('#new-campaign')?.addEventListener('click',()=>campaignModal(null,ctx));
  $$('[data-edit-campaign]').forEach(btn=>btn.addEventListener('click',()=>campaignModal(data.campaigns.find(x=>x.id===btn.dataset.editCampaign),ctx)));
}
function campaignModal(campaign,ctx){modal({title:campaign?'Edit campaign':'New campaign',body:`<form class="form-grid">${field('Title','title','text',campaign?.title||'',true)}${selectField('Channel','channel',[['LinkedIn','LinkedIn'],['Facebook','Facebook'],['Instagram','Instagram'],['Email','Email'],['Blog','Blog']],campaign?.channel||'LinkedIn')}${selectField('Status','status',[['Draft','Draft'],['Approved','Approved'],['Scheduled','Scheduled']],campaign?.status||'Draft')}${field('Scheduled date','scheduled_at','datetime-local',campaign?.scheduled_at?.slice(0,16)||'')}<div class="field full"><label>Content</label><textarea name="content" style="min-height:180px">${esc(campaign?.content||'')}</textarea></div></form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-campaign">Save</button>`,onOpen:(root,close)=>$('#save-campaign',root).addEventListener('click',async()=>{const body={title:$('[name=title]',root).value,channel:$('[name=channel]',root).value,status:$('[name=status]',root).value,scheduled_at:$('[name=scheduled_at]',root).value||null,content:$('[name=content]',root).value};try{await api(campaign?`/api/campaigns/${campaign.id}`:`/api/tenants/${state.selectedTenantId}/campaigns`,{method:campaign?'PATCH':'POST',body});toast('Campaign saved');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}

async function website(page,ctx){
  const data=await api(`/api/tenants/${state.selectedTenantId}/website`);const site=data.site;
  if(!state.selectedWebsitePageId||!data.pages.some(p=>p.id===state.selectedWebsitePageId))state.selectedWebsitePageId=data.pages[0]?.id;
  const selectedPage=data.pages.find(p=>p.id===state.selectedWebsitePageId);const pageSections=data.sections.filter(s=>s.page_id===selectedPage?.id).sort((a,b)=>a.position-b.position);
  if(!state.selectedWebsiteSectionId||!pageSections.some(s=>s.id===state.selectedWebsiteSectionId))state.selectedWebsiteSectionId=pageSections[0]?.id;
  const selectedSection=pageSections.find(s=>s.id===state.selectedWebsiteSectionId);
  const managed=site.mode==='managed';
  page.innerHTML=`${pageHead('Website Studio',managed?'Build and maintain a professional RMR-managed website from approved design systems and sections.':'Manage the connected website record and platform integrations.',`<a class="button secondary" href="${esc(data.public_url)}" target="_blank">Open website</a>${managed?`<button class="button" id="save-site">Save design</button>`:''}`)}
  ${!managed?`<section class="card"><h2>${site.mode==='external'?'Existing External Website':'Custom Connected Website'}</h2><p>Website URL: <strong>${esc(site.external_url||'Not configured')}</strong></p><div class="form-grid">${field('Website URL','external_url','url',site.external_url||'')}<div class="field"><label>Status</label><div>${badge(site.status,statusTone(site.status))}</div></div></div><button class="button" id="save-external-url">Save connection</button></section>`:`<div class="website-studio"><aside class="studio-panel"><section class="card"><h3>Design system</h3>${selectField('Template family','template_family',[['executive-authority','Executive Authority'],['bold-local-growth','Bold Local Growth'],['modern-agency','Modern Agency'],['community-impact','Community Impact']],site.template_family)}${field('Company name','company_name','text',site.company_name)}${field('Wordmark','wordmark','text',site.wordmark)}${colorField('Primary','primary_color',site.primary_color)}${colorField('Secondary','secondary_color',site.secondary_color)}${colorField('Accent','accent_color',site.accent_color)}${selectField('Heading font','heading_font',[['Georgia','Georgia'],['Arial','Arial'],['Trebuchet MS','Trebuchet MS'],['Times New Roman','Times New Roman']],site.heading_font)}${selectField('Button style','button_style',[['rounded','Rounded'],['square','Square'],['pill','Pill']],site.button_style)}</section><section class="card"><div style="display:flex;justify-content:space-between"><h3>Pages</h3><button class="button secondary small" id="add-page">+ Page</button></div><div class="page-list">${data.pages.map(p=>`<button class="list-item ${p.id===selectedPage?.id?'active':''}" data-page-id="${p.id}"><span class="grow"><strong>${esc(p.title)}</strong><small class="muted">/${esc(p.slug)} · ${esc(p.status)}</small></span></button>`).join('')}</div></section><section class="card"><div style="display:flex;justify-content:space-between"><h3>Sections</h3><button class="button secondary small" id="add-section">+ Section</button></div><div class="section-list">${pageSections.map(s=>`<button class="list-item ${s.id===selectedSection?.id?'active':''}" data-section-id="${s.id}"><span class="grow"><strong>${esc(title(s.section_type))}</strong><small class="muted">Position ${s.position}</small></span>${s.visible?badge('Visible','green'):badge('Hidden','gray')}</button>`).join('')}</div></section>${selectedSection?sectionEditor(selectedSection):''}</aside><section class="preview-shell"><div class="preview-toolbar"><strong class="grow">Live preview</strong><button class="button secondary small" data-preview-size="100%">Desktop</button><button class="button secondary small" data-preview-size="820px">Tablet</button><button class="button secondary small" data-preview-size="390px">Mobile</button></div><div style="display:flex;justify-content:center"><iframe class="preview-frame" id="website-preview" src="${esc(data.preview_url)}&page=${esc(selectedPage?.slug||'home')}" style="max-width:100%"></iframe></div></section></div>`}`;
  if(!managed){$('#save-external-url').addEventListener('click',async()=>{try{await api(`/api/tenants/${state.selectedTenantId}/website`,{method:'PATCH',body:{external_url:$('[name=external_url]').value}});toast('Website connection saved')}catch(e){toast(e.message,'error')}});return;}
  $$('[data-page-id]').forEach(btn=>btn.addEventListener('click',()=>{state.selectedWebsitePageId=btn.dataset.pageId;state.selectedWebsiteSectionId=null;ctx.navigate('website')}));
  $$('[data-section-id]').forEach(btn=>btn.addEventListener('click',()=>{state.selectedWebsiteSectionId=btn.dataset.sectionId;ctx.navigate('website')}));
  $$('[data-preview-size]').forEach(btn=>btn.addEventListener('click',()=>$('#website-preview').style.width=btn.dataset.previewSize));
  $('#save-site').addEventListener('click',async()=>{try{await api(`/api/tenants/${state.selectedTenantId}/website`,{method:'PATCH',body:{template_family:$('[name=template_family]').value,company_name:$('[name=company_name]').value,wordmark:$('[name=wordmark]').value,primary_color:$('[name=primary_color]').value,secondary_color:$('[name=secondary_color]').value,accent_color:$('[name=accent_color]').value,heading_font:$('[name=heading_font]').value,button_style:$('[name=button_style]').value}});toast('Website design saved');$('#website-preview').src=$('#website-preview').src.split('&_ts=')[0]+`&_ts=${Date.now()}`}catch(e){toast(e.message,'error')}});
  $('#save-section')?.addEventListener('click',async()=>{const settings={};$$('[data-section-setting]').forEach(input=>{let value=input.value;if(input.dataset.json==='1'){try{value=JSON.parse(value)}catch{toast('List must be valid JSON','error');throw new Error('invalid')}}settings[input.name]=value});try{await api(`/api/website/sections/${selectedSection.id}`,{method:'PATCH',body:{visible:$('#section-visible').checked,position:Number($('#section-position').value),settings}});toast('Section saved');ctx.navigate('website')}catch(e){if(e.message!=='invalid')toast(e.message,'error')}});
  $('#add-page').addEventListener('click',()=>addPageModal(ctx)); $('#add-section').addEventListener('click',()=>addSectionModal(selectedPage,ctx));
}
function sectionEditor(section){const s=section.settings_json||{};const fields=section.section_type==='hero'?`${field('Eyebrow','eyebrow','text',s.eyebrow||'')}${field('Headline','headline','text',s.headline||'')}${field('Supporting text','supporting_text','text',s.supporting_text||'')}${field('Primary button','primary_button','text',s.primary_button||'')}${field('Secondary button','secondary_button','text',s.secondary_button||'')}${selectField('Layout','layout',[['split','Split'],['centered','Centered'],['editorial','Editorial']],s.layout||'split')}`:section.section_type==='services'?`${field('Headline','headline','text',s.headline||'')}<div class="field"><label>Service items (JSON array)</label><textarea name="items" data-section-setting data-json="1">${esc(JSON.stringify(s.items||[],null,2))}</textarea></div>`:section.section_type==='metrics'?`${field('Headline','headline','text',s.headline||'')}<div class="field"><label>Metrics (JSON array)</label><textarea name="items" data-section-setting data-json="1">${esc(JSON.stringify(s.items||[],null,2))}</textarea></div>`:`${field('Headline','headline','text',s.headline||'')}<div class="field"><label>Body</label><textarea name="body" data-section-setting>${esc(s.body||'')}</textarea></div>`;return `<section class="card"><h3>Edit ${esc(title(section.section_type))}</h3><div class="field"><label>Position</label><input id="section-position" type="number" value="${section.position}"></div><label class="list-item"><input id="section-visible" type="checkbox" ${section.visible?'checked':''}> Visible</label><div class="grid" id="section-fields">${fields.replaceAll('name="','data-section-setting name="')}</div><button class="button" id="save-section">Save section</button></section>`}
function addPageModal(ctx){modal({title:'Add website page',body:`<form class="form-grid">${field('Page title','title','text','',true)}${field('URL slug','slug','text','',true)}${selectField('Status','status',[['draft','Draft'],['published','Published']])}<div class="field"><label><input type="checkbox" name="show_in_nav" checked> Show in navigation</label></div>${field('SEO title','seo_title','text','')}<div class="field full"><label>SEO description</label><textarea name="seo_description"></textarea></div></form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="create-page">Create page</button>`,onOpen:(root,close)=>$('#create-page',root).addEventListener('click',async()=>{try{const result=await api(`/api/tenants/${state.selectedTenantId}/website/pages`,{method:'POST',body:{title:$('[name=title]',root).value,slug:$('[name=slug]',root).value,status:$('[name=status]',root).value,show_in_nav:$('[name=show_in_nav]',root).checked,seo_title:$('[name=seo_title]',root).value,seo_description:$('[name=seo_description]',root).value}});state.selectedWebsitePageId=result.page.id;toast('Page created');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function addSectionModal(page,ctx){modal({title:'Add website section',body:`<form class="form-grid">${selectField('Section type','section_type',[['hero','Hero'],['services','Services'],['metrics','Performance metrics'],['text','Flexible text'],['contact','Contact form']])}${field('Position','position','number',10)}</form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="create-section">Add section</button>`,onOpen:(root,close)=>$('#create-section',root).addEventListener('click',async()=>{try{const type=$('[name=section_type]',root).value;const defaults=type==='hero'?{eyebrow:'NEW SECTION',headline:'Your headline',supporting_text:'Supporting message',primary_button:'Contact Us',layout:'split',background:'brand'}:type==='services'?{headline:'How we help',items:['Service one','Service two','Service three']}:type==='metrics'?{headline:'Progress you can see',items:[{value:'98%',label:'Client satisfaction'}]}:type==='contact'?{headline:'Ready to talk?',body:'Tell us how we can help.'}:{headline:'New content section',body:'Add your content here.'};const result=await api(`/api/tenants/${state.selectedTenantId}/website/sections`,{method:'POST',body:{page_id:page.id,section_type:type,position:Number($('[name=position]',root).value),settings:defaults}});state.selectedWebsiteSectionId=result.section.id;toast('Section added');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}

async function organization(page,ctx,readOnly){
  const data=await api(`/api/tenants/${state.selectedTenantId}/sales-organization`);
  const access=state.user.tenant_role==='CLIENT_ADMIN'&&!readOnly?await api(`/api/tenants/${state.selectedTenantId}/access`):null;
  const canManage=!readOnly && state.user.tenant_role==='CLIENT_ADMIN';
  const byId=Object.fromEntries(data.people.map(p=>[p.id,p]));
  page.innerHTML=`${pageHead('Sales Organization','Manage reporting relationships, teams, roles, and account ownership.',canManage?`<button class="button" id="add-person">+ Invite team member</button>`:'')}${readOnly?readonlyBanner():''}
  ${canManage&&access?.invitations?.some(i=>i.status==='pending')?`<div class="notice-card"><strong>Pending invitations</strong><p>${access.invitations.filter(i=>i.status==='pending').map(i=>esc(i.email)).join(', ')}</p></div>`:''}
  <section class="table-card"><div class="table-toolbar"><h2>People and reporting structure</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Name</th><th>Role</th><th>Team</th><th>Reports to</th><th>Accounts</th><th>Status</th>${canManage?'<th></th>':''}</tr></thead><tbody>${data.people.length?data.people.map(p=>`<tr><td><strong>${esc(p.full_name)}</strong><div class="tiny muted">${esc(p.email)}</div></td><td>${esc(roleLabel(p.tenant_role))}</td><td>${esc(p.team_name||'—')}</td><td>${esc(byId[p.manager_id]?.full_name||'—')}</td><td>${number(p.account_count)}</td><td>${badge(p.active?'Active':'Inactive',p.active?'green':'gray')}</td>${canManage?`<td><button class="button secondary small" data-edit-person="${p.id}">Edit</button></td>`:''}</tr>`).join(''):`<tr><td colspan="7">${empty('No team members','Invite the first user to establish the organization.')}</td></tr>`}</tbody></table></div></section>`;
  $('#add-person')?.addEventListener('click',()=>personModal(null,data.people,ctx));
  $$('[data-edit-person]').forEach(btn=>btn.addEventListener('click',()=>personModal(data.people.find(p=>p.id===btn.dataset.editPerson),data.people,ctx)));
}
function personModal(person,people,ctx){
  const roleOptions=[['CLIENT_ADMIN','Client Administrator'],['VP_SALES','VP of Sales'],['SALES_MANAGER','Sales Manager'],['SALES_REP','Sales Representative'],['MARKETING_USER','Marketing User'],['EXECUTIVE_VIEWER','Executive Viewer']];
  const managerOptions=[['','No manager'],...people.filter(p=>p.id!==person?.id).map(p=>[p.id,p.full_name])];
  modal({title:person?'Edit team member':'Invite team member',body:`<form id="person-form" class="form-grid">${field('Full name','full_name','text',person?.full_name||'',true)}${field('Email','email','email',person?.email||'',true)}${selectField('Role','tenant_role',roleOptions,person?.tenant_role||'SALES_REP')}${selectField('Reports to','manager_id',managerOptions,person?.manager_id||'')}${field('Team or region','team_name','text',person?.team_name||'')}${person?`<div class="field"><label><input type="checkbox" name="active" ${person.active?'checked':''}> Active user</label></div>`:''}</form>`,footer:`<button class="button secondary" data-close-modal>Cancel</button>${person?`<button class="button secondary" id="reset-person-password">Create reset link</button>`:''}<button class="button" id="save-person">${person?'Save':'Create invitation'}</button>`,onOpen:(root,close)=>{
    $('#save-person',root).addEventListener('click',async()=>{const form=$('#person-form',root);if(!form.reportValidity())return;const body={full_name:form.full_name.value,email:form.email.value,tenant_role:form.tenant_role.value,manager_id:form.manager_id.value||null,team_name:form.team_name.value};if(person)body.active=form.active.checked;try{const result=await api(person?`/api/tenant-users/${person.id}`:`/api/tenants/${state.selectedTenantId}/users`,{method:person?'PATCH':'POST',body});toast(person?'Team member updated':'Invitation created');close();if(result.activation_url)showSecureLink('Account activation link',result.activation_url);else ctx.navigate('organization')}catch(e){applyFieldErrors(root,e.fieldErrors);toast(e.message,'error')}});
    $('#reset-person-password',root)?.addEventListener('click',async()=>{try{const result=await api(`/api/tenant-users/${person.id}/reset-password`,{method:'POST',body:{}});if(result.reset_url)showSecureLink('Password reset link',result.reset_url);else toast('Password reset instructions were created')}catch(e){toast(e.message,'error')}});
  }});
}
function showSecureLink(titleText,url){modal({title:titleText,body:`<p>Share this one-time link securely with the intended user.</p><div class="secure-link"><code>${esc(url)}</code><button class="button secondary small" id="copy-secure-link">Copy</button><button class="button secondary small" id="open-secure-link">Open</button></div>`,footer:'<button class="button" data-close-modal>Done</button>',onOpen:root=>{$('#copy-secure-link',root).addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);toast('Link copied')}catch{toast('Copy unavailable','error')}});$('#open-secure-link',root).addEventListener('click',()=>window.open(url,'_blank','noopener'))}})}
function roleLabel(role){return ({CLIENT_ADMIN:'Client Administrator',VP_SALES:'VP of Sales',SALES_MANAGER:'Sales Manager',SALES_REP:'Sales Representative',MARKETING_USER:'Marketing User',EXECUTIVE_VIEWER:'Executive Viewer'})[role]||role}

async function training(page){
  const data=await api('/api/training');
  page.innerHTML=`${pageHead('Training Library','Role-focused guidance for business practice and deeper workflows.')}
  <div class="grid three">${data.resources.map(r=>`<section class="card"><div style="display:flex;justify-content:space-between">${badge(r.module,'gray')}${r.required?badge('Required','amber'):badge('Optional','gray')}</div><div style="height:120px;border-radius:14px;background:linear-gradient(135deg,#0d2b4c,#315efb);display:grid;place-items:center;color:#fff;font-size:2rem;margin:14px 0">▶</div><h3>${esc(r.title)}</h3><p class="muted">${esc(r.description)}</p><div class="tiny muted">${r.duration_minutes} min · ${r.media_type.replace('_',' ')}</div><div class="progress-bar" style="margin:14px 0"><span style="width:${r.progress?.progress_pct||0}%"></span></div><div style="display:flex;gap:8px"><a class="button secondary small" href="${r.media_url||'#'}" target="_blank">Open resource</a><button class="button small" data-complete-training="${r.id}">${r.progress?.status==='complete'?'Completed':'Mark complete'}</button></div></section>`).join('')}</div>`;
  $$('[data-complete-training]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/training/${btn.dataset.completeTraining}/progress`,{method:'PATCH',body:{status:'complete',progress_pct:100}});toast('Training marked complete');location.hash='#/training';window.dispatchEvent(new HashChangeEvent('hashchange'))}catch(e){toast(e.message,'error')}}));
}

function kpi(label,value,note){return `<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></div>`}
function title(value){return String(value||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
function field(label,name,type='text',value='',required=false){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`}
function selectField(label,name,options,selected=''){return `<div class="field"><label>${label}</label><select name="${name}">${options.map(([value,text])=>`<option value="${value}" ${value===selected?'selected':''}>${esc(text)}</option>`).join('')}</select></div>`}
function colorField(label,name,value){return `<div class="field"><label>${label} color</label><div class="color-field"><input type="color" name="${name}" value="${esc(value)}"><code>${esc(value)}</code></div></div>`}
function solutionIcon(code){return ({crm:'C',forecasting:'F',forecasting_management:'F',management_intelligence:'M',managed_website:'W',custom_website_connection:'W',external_website_connection:'W',piq_access:'P',piq_enhancement:'P',campaigns:'C',training:'T',monthly_seo:'S',platform_core:'R'})[code]||'+'}
function routeForService(code){if(code==='crm')return'crm';if(['forecasting','forecasting_management'].includes(code))return'forecast';if(code==='management_intelligence')return'reports';if(code==='piq_access')return'piq';if(['managed_website','custom_website_connection','external_website_connection'].includes(code))return'website';if(code==='campaigns')return'campaigns';if(code==='training')return'training';return'home'}
function downloadCsv(filename,headers,rows){const csv=[headers,...rows].map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
